import os
import pygame
from mutagen.mp3 import MP3
from mutagen.easyid3 import EasyID3

def create_audio_cache():
    cache_dir = ""audio_cache""
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)

def load_audio_file(file_path):
    audio_file = None
    if not file_path:
        for filename in os.listdir(""audio_cache""):
            if filename.endswith("".mp3""):
                file_path = os.path.join(""audio_cache"", filename)
                break
    return file_path

def extract_metadata(file_path):
    metadata = {}
    try:
        audio_file = MP3(file_path)
        tags = EasyID3(file_path).tags
        metadata['title'] = tags['TIT2'][0]
        metadata['artist'] = tags['TPE1'][0]
        metadata['album'] = tags['TALB'][0]
        metadata['genre'] = tags['TGEN'][0]
    except:
        pass
    return metadata

def main():
    create_audio_cache()
    file_path = load_audio_file(None)
    metadata = extract_metadata(file_path)
    print(metadata)

if __name__ == ""__main__"":
    main()
