def max_subarray_sum(lst):
    if not lst:
        return None

    max_current = max_global = lst[0]

    for num in lst[1:]:
        max_current = max(num, max_current + num)
        max_global = max(max_global, max_current)

    if all(x < 0 for x in lst):
        return max(lst)

    return max_global']",79,[0],[],True,0,0,0,

