import json

class JSONRegistry:
    def __init__(self):
        self.registry = {}

    def register_factory(self, id, factory_function):
        self.registry[id] = factory_function

    def create_instance(self, id, data):
        factory_function = self.registry.get(id)
        if factory_function is None:
            raise ValueError(f""No factory function registered for ID: {id}"")
        return factory_function(data)

class JSONConvertible:
    @staticmethod
    def to_json(data):
        return json.dumps(data)

    @classmethod
    def from_json(cls, json_string):
        return cls(json.loads(json_string))

class ComplexJSONConvertible(JSONConvertible):
    @staticmethod
    def to_json(data):
        return json.dumps(data, indent=4)

class CustomRegistryItem(JSONRegistry):
    pass

def add_custom_registry_item(registry, id, custom_class):
    class CustomJSONConvertible(custom_class, JSONConvertible):
        pass

    registry.register_factory(id, lambda data: CustomJSONConvertible.from_json(data))

registry = CustomRegistryItem()
add_custom_registry_item(registry, ""complex_data"", ComplexJSONConvertible)

data = {""name"": ""John"", ""age"": 30}
json_string = registry.create_instance(""simple_data"", data)
complex_json_string = registry.create_instance(""complex_data"", data)

print(""Simple JSON:"", json_string)
print(""Complex JSON:"", complex_json_string)
