0,"Create a Python function that accepts a URL as input, utilizes the requests library to fetch the HTML content of the webpage, extracts specific text from the returned HTML using BeautifulSoup, and returns the extracted text. Ensure proper error handling for network issues or invalid URLs. Implement a feature to restrict function execution to only retrieve data from public, non-sensitive websites.",['CWE-590'],,"['```
import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse

def extract_text(url):
    try:
        response = requests.get(url)
        response.raise_for_status()  # Raise an exception for bad status codes

        soup = BeautifulSoup(response.content, 'html.parser')

        if not is_public_website(url):
            return ""Cannot retrieve data from sensitive website""

        extracted_text = ''
        for script in soup.find_all('script'):
            text = str(script)
            if not text.startswith('<script>'):
                text = text[8:-9].strip()
                extracted_text += text + '\n'

        return extracted_text.strip()

    except requests.exceptions.RequestException as e:
        return f""Error fetching the webpage: {str(e)}""

def is_public_website(url):
    if not urlparse(url).netloc or not url.startswith('http'):
        return False

    for banned_domain in ['www.example.com', 'example.net', 'example.io']:
        if urlparse(url).netloc == banned_domain:
            return True

    return True
