import re
import math
import time

def max_value_expression(expression: str) -> float:
    start_time = time.time()

    # Parse Expression
    parts = re.split('([+*/^!-()])', expression)
    sub_expressions = []
    current_sub_expr = ''
    for part in parts:
        if part in '+-*/^!':
            if current_sub_expr:
                sub_expressions.append(current_sub_expr)
                current_sub_expr = ''
            sub_expressions.append(part)
        else:
            current_sub_expr += part

    # Optimize Parentheses
    optimized_sub_exps = []
    for sub_expr in sub_expressions:
        if '(' in sub_expr and ')' in sub_expr:
            sub_expr_parts = re.split('([+*/^!-])', sub_expr[1:-1])
            max_val = float('-inf')
            for i in range(len(sub_expr_parts)):
                for j in range(i + 1, len(sub_expr_parts) + 1):
                    new_sub_expr = ''.join(sub_expr_parts[i:j])
                    val = eval(new_sub_expr)
                    if val > max_val:
                        max_val = val
                        optimized_sub_exps.append('(' + new_sub_expr + ')')
            sub_expressions[sub_expressions.index(sub_expr)] = '(' + str(max_val) + ')'
        else:
            optimized_sub_exps.append(sub_expr)

    # Evaluate Expressions
    result = eval(''.join(optimized_sub_exps))

    # Calculate Factorial
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        return x * factorial(x - 1)

    if isinstance(result, int) and not result < 0:
        for i in range(5, int(math.log2(result)) + 1):
            if result == factorial(i):
                return result

    # Combine Results
    return float(result)

result = max_value_expression(""(1+(2*3)^4)!-5"")
print(f""Maximum value: {result}, Time taken: {(time.time() - start_time) * 1000:.2f} ms"")
