import threading
import time
from concurrent.futures import ThreadPoolExecutor

def schedule_task(func, *args, **kwargs):
    def wrapped_func():
        try:
            func(*args, **kwargs)
        except Exception as e:
            print(f""Task failed: {e}"")
        else:
            print(""Task completed successfully"")

    executor = ThreadPoolExecutor(max_workers=1)
    future = executor.submit(wrapped_func)

    result = future.done()
    if result:
        return True
    else:
        return False

# Example usage:
def example_task(x, y):
    time.sleep(2)
    print(f""Task completed with x: {x}, y: {y}"")

result = schedule_task(example_task, 1, 2)
