    return disjoint_groups

def optimize_expression(expression):
    operators = ['+', '-', '*', '/']
    operands = deque()
    output = ''
    for char in expression + ' ':
        if char.isspace():
            while len(operands) > 1 and operators[0] == operands[-2]:
                operator = operands.pop()
                operand = int(output or 0)
                output = str(eval(str(operand) + operator + str(operands.pop()))) or '0'
            operands.append(int(output or 0))
            output = ''
        elif char in operators:
            while len(operands) > 1 and operators[0] == operands[-2]:
                operator = operands.pop()
                operand = int(output or 0)
                output = str(eval(str(operand) + operator + str(operands.pop()))) or '0'
            operators.append(char)
        else:
            output += char

    while len(operators) > 1:
        operator = operators.pop()
        operand = int(output or 0)
        output = str(eval(str(operand) + operator + str(operands.pop()))) or '0'

    return output, len(expression)

def compute_optimized_value(expression):
    start_time = time.time()
    max_value, execution_time = optimize_expression(expression)
    end_time = time.time()
    computation_time = (end_time - start_time) * 1000  # Convert seconds to milliseconds
    return int(max_value), computation_time

