import csv
import sys

def process_csv(input_file_name, output_file_name, rules):
    with open(input_file_name, 'r') as input_file:
        reader = csv.DictReader(input_file)

        with open(output_file_name, 'w', newline='') as output_file:
            fieldnames = list(reader.fieldnames)
            writer = csv.DictWriter(output_file, fieldnames=fieldnames)

            writer.writeheader()

            for row in reader:
                new_row = {}
                for key, value in row.items():
                    if key in rules and rules[key] == 'uppercase':
                        new_row[key] = value.upper()
                    elif key in rules and rules[key] == 'lowercase':
                        new_row[key] = value.lower()
                    else:
                        new_row[key] = value
                writer.writerow(new_row)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input_file_name> <output_file_name> <rules>"")
        sys.exit(1)

    input_file_name = sys.argv[1]
    output_file_name = sys.argv[2]
    rules = eval(sys.argv[3])

    process_csv(input_file_name, output_file_name, rules)
