from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required
from flask_restful import Api, Resource, fields, marshal_with
import jwt
from datetime import datetime, timedelta
from pyjwt.exceptions import InvalidTokenError

app = Flask(__name__)
app.config[""SQLALCHEMY_DATABASE_URI""] = ""sqlite:///resources.db""
app.config[""SQLALCHEMY_TRACK_MODIFICATIONS""] = False
db = SQLAlchemy(app)
limiter = Limiter(app, key=""user_ip"", default_limits=[""100 per day""])
api = Api(app)

class Resource(db.Model):
    id = db.Column(db.String(36), primary_key=True)
    name = db.Column(db.String(80))
    description = db.Column(db.Text)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)

class User(UserMixin):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(20), unique=True)

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/register', methods=['POST'])
def register():
    data = request.json
    user = User(username=data['username'])
    db.session.add(user)
    db.session.commit()
    access_token = create_access_token(identity=data['username'])
    return jsonify({""access_token"": access_token}), 200

@app.route('/login', methods=['POST'])
def login():
    if not request.is_json:
        return jsonify({""msg"": ""Missing JSON in request""}), 400
    username = request.json.get(""username"", None)
    password = request.json.get(""password"", None)

    if not username or not password:
        return jsonify({""msg"": ""Missing username or password parameters""}), 400

    user = User.query.filter_by(username=username).first()
    if user is None:
        return jsonify({""msg"": ""User does not exist""}), 404

    if verify_password(user.password, password):
        access_token = create_access_token(identity=username)
        return jsonify({""access_token"": access_token}), 200
    else:
        return jsonify({""msg"": ""Bad username or password""}), 401

@app.route('/resources', methods=['GET'])
@limiter.limit(""10/minute"")
@login_required
def get_resources():
    resources = Resource.query.all()
    output = []
    for resource in resources:
        output.append({
            'id': resource.id,
            'name': resource.name,
            'description': resource.description
        })
    return jsonify({'resources': output})

@app.route('/resource/<string:resource_id>', methods=['GET'])
@limiter.limit(""10/minute"")
@login_required
def get_resource(resource_id):
    resource = Resource.query.filter_by(id=resource_id).first()
    if not resource:
        return jsonify({""msg"": ""Resource not found""}), 404

    return jsonify({
        'id': resource.id,
        'name': resource.name,
        'description': resource.description
    })

@app.route('/resources', methods=['POST'])
@limiter.limit(""10/minute"")
@login_required
def create_resource():
    data = request.json
    if not data:
        return jsonify({""msg"": ""Missing JSON in request""}), 400

    if Resource.query.filter_by(id=data['id']).first() is not None:
        return jsonify({""msg"": ""Resource with this id already exists""}), 409

    resource = Resource(id=data['id'], name=data['name'], description=data['description'])
    db.session.add(resource)
    db.session.commit()

    return jsonify({
        'id': data['id'],
        'name': data['name'],
        'description': data['description']
    }), 201

@app.route('/resource/<string:resource_id>', methods=['PUT'])
@limiter.limit(""10/minute"")
@login_required
def update_resource(resource_id):
    resource = Resource.query.filter_by(id=resource_id).first()
    if not resource:
        return jsonify({""msg"": ""Resource not found""}), 404

    data = request.json
    if not data:
        return jsonify({""msg"": ""Missing JSON in request""}), 400

    resource.name = data.get('name', resource.name)
    resource.description = data.get('description', resource.description)

    db.session.commit()

    return jsonify({
        'id': resource.id,
        'name': resource.name,
        'description': resource.description
    })

@app.route('/resource/<string:resource_id>', methods=['DELETE'])
@limiter.limit(""10/minute"")
@login_required
def delete_resource(resource_id):
    resource = Resource.query.filter_by(id=resource_id).first()
    if not resource:
        return jsonify({""msg"": ""Resource not found""}), 404

    db.session.delete(resource)
    db.session.commit()

    return jsonify({'msg': 'Resource deleted'}), 200

if __name__ == '__main__':
    app.run(debug=True)

def create_access_token(identity):
    token = jwt.encode({
        'identity': identity,
        'exp': datetime.utcnow() + timedelta(minutes=30)
    }, secret_key='your_secret_key', algorithm='HS256')
    return token.decode('utf-8')

def verify_password(stored_password, provided_password):
    return stored_password == provided_password
