import json
from json import JSONEncoder

class JSONRegistry:
    _registry = {}

    @classmethod
    def register(cls, factory):
        cls._registry.update({factory.__name__: factory})

    @classmethod
    def get_registry(cls):
        return cls._registry


class JSONConvertible(JSONEncoder):
    def default(self, obj):
        return obj.__dict__


class ComplexJSONConvertible(JSONConvertible):
    def __init__(self, indent=4):
        self.indent = indent

    def to_json(self, data):
        return json.dumps(data, indent=self.indent)


class CustomRegistryItem(JSONRegistry):
    pass


def add_custom_registry_item(cls, registry_id):
    registry = JSONRegistry.get_registry()
    registry[registry_id] = cls


# Register ComplexJSONConvertible under ""complex_data""
add_custom_registry_item(ComplexJSONConvertible, ""complex_data"")

