complex_data = {""data"": [{""id"": 1, ""name"": ""Alice""}, {""id"": 2, ""name"": ""Bob""}]}

json_simple_data = json.dumps(simple_data)
json_complex_data = ComplexJSONConvertible().to_json(complex_data)

print(""Simple Data JSON:"", json_simple_data)
print(""Complex Data JSON:"", json_complex_data)
