import csv
import sys

def transform_data(input_file, output_file, rules):
    with open(input_file, 'r') as file:
        reader = csv.DictReader(file)

        with open(output_file, 'w', newline='') as outf:
            writer = csv.DictWriter(outf, fieldnames=reader.fieldnames)

            if not rules:
                for row in reader:
                    writer.writerow(row)
            else:
                for row in reader:
                    new_row = {}
                    for key, value in row.items():
                        if key in rules:
                            # Apply rule based on the column name
                            if value == rules[key][0]:
                                new_row[key] = rules[key][1]
                            else:
                                new_row[key] = value
                        else:
                            new_row[key] = value
                    writer.writerow(new_row)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input_file> <output_file> <rules>"")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    rules = {}

    # Parse processing rules from command-line argument
    for rule in sys.argv[3].split(','):
        pair = rule.split('=')
        if len(pair) == 2:
            key, value = pair
            rules[key] = [value, value]

    transform_data(input_file, output_file, rules)
