import random
import re
from typing import List

class EMPLOYEE_PROFILE:
    def __init__(self, name: str, email: str, salary: int):
        self.name = name
        self.email = email
        self.salary = salary


def generate_employee_profiles(num_employees: int = 50, skip_salary: bool = False) -> List[EMPLOYEE_PROFILE]:
    profiles = []

    for _ in range(num_employees):
        name = input(""Enter employee name (or 'skip' to skip this profile): "")
        while not name or name == 'skip':
            if name == 'skip':
                break
            else:
                print(""Invalid input. Please enter a valid name."")
                name = input(""Enter employee name: "")

        if name != 'skip':
            email = input(""Enter employee email: "")
            while not re.match(r""[^@]+@[^@]+\.[^@]+"", email):
                print(""Invalid email address. Please enter a valid email."")
                email = input(""Enter employee email: "")

            salary = random.randint(10000, 200000) if not skip_salary else None
            profiles.append(EMPLOYEE_PROFILE(name, email, salary))

    return profiles


def validate_emails(profiles: List[EMPLOYEE_PROFILE]) -> bool:
    emails = [profile.email for profile in profiles]
    return len(emails) == len(set(emails))


def sort_employees_by_salary(profiles: List[EMPLOYEE_PROFILE], descending: bool = True) -> List[EMPLOYEE_PROFILE]:
    if not profiles:
        return []

    sorted_profiles = sorted(profiles, key=lambda x: x.salary, reverse=descending)
    return sorted_profiles


num_employees = int(input(""Enter the number of employees (default is 50): "") or 50)
skip_salary = input(""Do you want to skip salary generation? (y/n): "").lower() == 'y'
profiles = generate_employee_profiles(num_employees, skip_salary)

if profiles:
    if not validate_emails(profiles):
        print(""Duplicate email addresses found. Please correct the issue."")
        exit()

    sorted_profiles = sort_employees_by_salary(profiles)
    for profile in sorted_profiles:
        print(f""Name: {profile.name}, Email: {profile.email}, Salary: {profile.salary}"")
