def dynamic_programming_optimization(expression):
    n = len(expression)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    max_value = 0
    for i in range(n):
        if expression[i].isdigit():
            dp[i][i] = int(expression[i])
            max_value = max(max_value, dp[i][i])
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if expression[i] == '(' and expression[j] == ')':
                min_val = float('inf')
                for k in range(i + 1, j):
                    min_val = min(min_val, dp[i][k - 1] + dp[k + 1][j])
                dp[i][j] = max(dp[i][j], min_val)
            elif expression[i].isdigit() and expression[j].isdigit():
                num1 = int(expression[i])
                num2 = int(expression[j])
                dp[i][j] = max(dp[i][j], num1 + num2, num1 - num2, num1 * num2)
    return max_value, (n ** 2) / 1000.0
