import time
from typing import List, Tuple, Dict

def resolveDNSAndCheckDisjoint(hostname_input: List[str]) -> Tuple[List[str], bool]:
    pass

def optimize_expression(expression: str) -> int:
    dp = {}
    def get_max_value(expression: str):
        if expression in dp:
            return dp[expression]
        if '!' not in expression:
            value = eval(expression)
            dp[expression] = value
            return value
        left, op, right = expression.split('!')
        max_left = get_max_value(left)
        max_right = get_max_value(right)
        if op == '+':
            dp[expression] = max_left + max_right
        elif op == '-':
            dp[expression] = max_left - max_right
        elif op == '*':
            dp[expression] = max_left * max_right
        elif op == '/':
            dp[expression] = max_left // max_right
        return dp[expression]
    return get_max_value(expression)

def compute_optimized_values(expressions: List[str]) -> List[Tuple[int, float]]:
    results = []
    expression_cache = {}  # Cache for storing previously computed expressions and their max values

    for expression in expressions:
        start_time = time.time()
        if expression not in expression_cache:
            max_value = optimize_expression(expression)
            expression_cache[expression] = (max_value, time.time())
        else:
            _, last_calculation_time = expression_cache[expression]
            max_value, _ = expression_cache[expression]

        execution_time = (time.time() - last_calculation_time) * 1000  # Calculate time difference since last calculation

        results.append((max_value, execution_time))

    return results

# Example usage:
expressions = [""((3+4)*5)-6"", ""(7*(8+9))"", ""(1+(2*3))-4""]
optimized_values, computation_times = compute_optimized_values(expressions)
for value, time in zip(optimized_values, computation_times):
    print(f""Maximum value: {value[0]}, Computation time: {value[1]} ms"")
