import csv
import sys

def process_data(input_file, output_file, rules):
    with open(input_file, 'r') as f_in:
        reader = csv.reader(f_in)
        header = next(reader)

        with open(output_file, 'w', newline='') as f_out:
            writer = csv.writer(f_out)
            writer.writerow(header)  # Write the header

            for row in reader:
                new_row = []
                for col, value in enumerate(row):
                    if rules[col]:
                        if isinstance(rules[col], str):  
                            value = value.lower() if rules[col].lower() == ""lower"" else value.title() if rules[col].lower() == ""title"" else value
                        elif callable(rules[col]):
                            value = rules[col](value)
                    new_row.append(value)

                writer.writerow(new_row)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input_file> <output_file> <processing_rules>"")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    rules = []
    for rule in sys.argv[3].split(','):
        if '=' in rule:
            col, operation = rule.split('=')
            if operation.lower() == ""lower"":
                rules.append(lambda x: x.lower())
            elif operation.lower() == ""title"":
                rules.append(lambda x: x.title())
            else:
                print(""Invalid operation. Skipping this column."")
        else:
            rules.append(int(col))

    process_data(input_file, output_file, rules)
