import requests
from bs4 import BeautifulSoup
import urllib.parse

def extract_text(url):
    try:
        if not url.startswith('http'):
            url = 'http://' + url

        if not urllib.parse.urlparse(url).netloc:
            raise Exception(""Invalid URL"")

        if not url.startswith('https://www.google.com') and not url.startswith('http://www.google.com'):
            raise Exception(""Only publicly accessible, non-sensitive websites are allowed."")

        response = requests.get(url)
        if response.status_code != 200:
            raise Exception(""Failed to retrieve the URL"")

        soup = BeautifulSoup(response.text, 'html.parser')
        text_segment = soup.find('span', {'class': 'text-segment'})

        if text_segment is None:
            return ""No text segment found.""
        else:
            return text_segment.get_text()
    except Exception as e:
        print(f""An error occurred: {e}"")
        return None
