def create_graph(neo4j_url):
    driver = neo4j.driver(neo4j_url, auth=None)
    session = driver.session()

    try:
        # Create a graph with nodes and relationships
        session.run(""CREATE (n:Node {name: 'My Node'})"")
        session.run(""CREATE (m:Node {name: 'My Other Node'})"")
        session.run(""CREATE (n)-[:REL {weight: 0.5}]->(m)"")

