        address = f'http://localhost:8000/node_{random.randint(1, 100)}'
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        status = random.choice(['online', 'offline', 'maintenance'])
        instances_array.append(NODE_INSTANCE_TYPES(address=address,
                                                   timestamp=timestamp,
                                                   status=status))
    return instances_array

if fetch_node_details():
    instances_array = generate_node_instance_types_array(5)
