class UnionFind:
    def __init__(self):
        self.parent = {}

    def find(self, x):
        if self.parent[x] != x:
            self.parent[self.parent[x]] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        self.parent.setdefault(x, x)
        self.parent.setdefault(y, y)
        self.parent[self.find(x)] = self.find(y)

def resolveDNSAndCheckDisjoint(hostnames):
    uf = UnionFind()
    for hostname in hostnames:
        if '.' not in hostname:
            continue
        domain = '.'.join(hostname.split('.')[1:])
        root = '.'.join(hostname.split('.')[:-1])
