def optimize_expression(expression):
    n = len(expression)
    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length
            for k in range(i, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j] + (expression[i - 1] == '(' and expression[j] == ')'))
    return dp[0][n]

def compute_optimized_values(expressions):
