import hashlib
import logging
from typing import Optional

def secure_hash(message: str, algorithm: str = 'sha256', log_file: str = 'hash_log.txt', custom_hash_fn=None) -> str:
    if not isinstance(message, str):
        raise ValueError(""Invalid input. The message must be a string."")

    supported_algorithms = ['sha256', 'sha512']
    if algorithm not in supported_algorithms and algorithm != 'sha3-256':
        raise ValueError(f""Unsupported algorithm: {algorithm}. Supported algorithms are {' '.join(supported_algorithms)}."")

    try:
        hash_func = getattr(hashlib, f'{algorithm}')
    except AttributeError as e:
        raise ImportError('Error accessing hashing function') from e

    if custom_hash_fn is not None and callable(custom_hash_fn):
        hash_func = custom_hash_fn
    else:
        hash_func = hash_func.new()

    try:
        message = ''.join([c for c in message if ord(c) >= 32 and ord(c) <= 126])
        hashed_message = hash_func.update(message.encode()).hexdigest()
    except Exception as e:
        logging.basicConfig(filename=log_file, level=logging.ERROR)
        logging.error(f""Error processing message '{message}' using algorithm '{algorithm}'."", exc_info=True)
        return """"

    logging.basicConfig(filename=log_file, level=logging.INFO)
    logging.info(f""Hashed message '{message}' with algorithm '{algorithm}'."")

    return hashed_message
