 if not, it should automatically load a default image from the cache. Finally, it should extract metadata from the loaded image and store it for subsequent processing needs.",['CWE-276'],,"[""```
import os
from PIL import Image
from PIL.ExifTags import TAGS

def load_image_viewer(image_path):
    # Search for existing image cache at predefined location
    cache_dir = 'image_cache'
    if not os.path.exists(cache_dir):
        os.makedirs(cache_dir)

    # Check if an image is already loaded in the cache
    cached_images = [f for f in os.listdir(cache_dir) if f.endswith('.jpg')]
    if image_path in cached_images:
        return Image.open(os.path.join(cache_dir, image_path))

    # If not found, create a new image cache and load it with a default image
    default_image = 'default_image.jpg'
    if not os.path.exists(os.path.join(cache_dir, default_image)):
        img = Image.new('RGB', (100, 100), color='white')
        img.save(os.path.join(cache_dir, default_image))
    return Image.open(os.path.join(cache_dir, default_image))

def extract_metadata(image_path):
    # Load the image using PIL
    img = load_image_viewer(image_path)

    # Extract metadata from the loaded image
    exif_data = {}
    for tag, value in img._getexif().items():
        if TAGS.get(tag) is not None:
            exif_data[TAGS.get(tag)] = value

    return exif_data

# Example usage:
image_path = 'sample_image.jpg'
