0,"Design a Python function responsible for creating a WebSocket client and providing a ConnectionManager for a specified endpoint. This function should include an optional parameter to enable message framing, offering flexibility in handling data transmission.",['CWE-295'],,"['```
import asyncio
import websockets

class ConnectionManager:
    def __init__(self):
        self.websocket = None

    async def connect(self, endpoint, enable_framing=False):
        try:
            self.websocket = await websockets.connect(endpoint)
            if not enable_framing:
                return self.websocket
            while True:
                message = await self.websocket.recv()
                print(f""Received: {message}"")
        except Exception as e:
            print(f""Error connecting to {endpoint}: {str(e)}"")
            self.websocket = None

    async def send(self, data):
        if not self.websocket:
            raise ValueError(""Not connected to the server"")
        try:
            await self.websocket.send(data)
        except Exception as e:
            print(f""Error sending data: {str(e)}"")

    async def close(self):
        if self.websocket:
            try:
                await self.websocket.close()
            except Exception as e:
                print(f""Error closing connection: {str(e)}"")
            self.websocket = None

# Example usage
async def main():
    cm = ConnectionManager()
    await cm.connect(""ws://localhost:12345"", enable_framing=True)
    while True:
        message = input(""Enter a message to send (or 'q' to quit): "")
        if message.lower() == 'q':
            break
        await cm.send(message.encode())
    await cm.close()

asyncio.run(main())
