import time
import psutil
import atexit

def measure_script_execution(script):
    def get_cpu_usage():
        return psutil.cpu_percent()

    def exit_hook():
        pass  # Implement your cleanup tasks here

    start_time = time.time()
    start_cpu = get_cpu_usage()

