        exec(script)
    except Exception as e:
        print(f""Script execution failed with error: {str(e)}"")
        return -1

    end_time = time.time()
    end_cpu = get_cpu_usage()

    elapsed_time = end_time - start_time
    cpu_diff = end_cpu - start_cpu

    exit_status = 0

    atexit.register(exit_hook)

