import rsa
import getpass
from cryptography.fernet import Fernet
import os

class RSACrypto:
    def __init__(self):
        self.keys_dir = 'keys'

    def generate_keys(self, username):
        private_key, public_key = rsa.newkeys(512)
        key_file = f'{self.keys_dir}/{username}_private.pem'
        pub_key_file = f'{self.keys_dir}/{username}_public.pem'

        with open(key_file, 'wb') as f:
            f.write(private_key.save_pkcs1('PEM'))

        with open(pub_key_file, 'wb') as f:
            f.write(public_key.save_pkcs1('PEM'))

    def encrypt_message(self, public_key, message):
        try:
            encrypted_message = rsa.encrypt(message.encode(), public_key)
            return encrypted_message
        except Exception as e:
            print(f""Encryption failed: {str(e)}"")
            return None

    def decrypt_message(self, private_key, encrypted_message):
        try:
            decrypted_message = rsa.decrypt(encrypted_message, private_key)
            return decrypted_message.decode()
        except Exception as e:
            print(f""Decryption failed: {str(e)}"")
            return None

    def main(self):
        username = input(""Enter your username: "")

        if not os.path.exists(self.keys_dir):
            os.makedirs(self.keys_dir)

        if not os.path.exists(f'{self.keys_dir}/{username}_private.pem'):
            self.generate_keys(username)

        private_key_file = f'{self.keys_dir}/{username}_private.pem'
        pub_key_file = f'{self.keys_dir}/{username}_public.pem'

        try:
            with open(private_key_file, 'rb') as f:
                private_key = rsa.PrivateKey.load_pkcs1(f.read())

            with open(pub_key_file, 'rb') as f:
                public_key = rsa.PublicKey.load_pkcs1(f.read())

            message = input(""Enter your message: "")

            encrypted_message = self.encrypt_message(public_key, message)
            if encrypted_message:
                print(f""Encrypted message: {encrypted_message.hex()}"")

            decrypted_message = self.decrypt_message(private_key, bytes.fromhex(encrypted_message.hex()))
            if decrypted_message:
                print(f""Decrypted message: {decrypted_message}"")

        except FileNotFoundError as e:
            print(f""Key not found: {str(e)}"")
        except Exception as e:
            print(f""An error occurred: {str(e)}"")

if __name__ == ""__main__"":
    RSACrypto().main()
