import json
from typing import List, Dict

def process_json_objects(json_strings: List[str], target_keys: List[str]) -> Dict:
    output_dict = {key: [] for key in target_keys}

    for json_string in json_strings:
        try:
            json_object = json.loads(json_string)
            for key in target_keys:
                if isinstance(json_object, dict):
                    if key in json_object:
                        output_dict[key].append(json_object.get(key))
                    else:
                        output_dict[key].append('N/A')
                elif isinstance(json_object, list):
                    for obj in json_object:
                        if isinstance(obj, dict) and key in obj:
                            output_dict[key].append(obj.get(key))
                        elif not output_dict[key]:
                            output_dict[key].append('N/A')
        except ValueError:
            print(f""Invalid JSON format: {json_string}"")

    return output_dict
