import random
from Crypto.Util.number import getPrime
from Crypto.PublicKey import RSA
from Crypto.Signature import pkcs1_15
from hashlib import sha256


def generate_prime(length):
    while True:
        prime = getPrime(length)
        if is_prime(prime):
            return prime


def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True


class RSAKeyManager:
    def __init__(self, key_size=2048):
        self.keys = {}

    def generate_key(self, key_name, public_exponent=65537):
        while True:
            p = generate_prime(key_size//2)
            q = generate_prime(key_size//2)
            if p != q and is_prime(p) and is_prime(q):
                n = p * q
                phi = (p - 1) * (q - 1)
                e = random.randint(3, public_exponent-1)
                while gcd(e, phi) != 1:
                    e = random.randint(3, public_exponent-1)
                d = mod_inverse(e, phi)
                self.keys[key_name] = RSA.construct((n, e, d))
                return self.keys[key_name]

    def encrypt(self, message):
        for key_name, key in self.keys.items():
            if key.can_encrypt:
                try:
                    cipher_text = key.encrypt(message.encode())
                    return cipher_text, key
                except ValueError as e:
                    print(f""Error: {e}"")
        return None

    def decrypt(self, cipher_text):
        for key_name, key in self.keys.items():
            if key.can_decrypt:
                try:
                    plain_text = key.decrypt(cipher_text)
                    return plain_text.decode()
                except ValueError as e:
                    print(f""Error: {e}"")
        return None


def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a


def mod_inverse(a, m):
    if gcd(a, m) != 1:
        return None
    t = 0
    newt = 1
    r = m
    newr = a
    while newr != 0:
        quotient = r // newr
        t, newt = newt, t - quotient * newt
        r, newr = newr, r - quotient * newr
    if r > 1:
        return None
    if t < 0:
        t += m
    return t


class RSAProcessor:
    def __init__(self):
        self.key_manager = RSAKeyManager()

    def process(self, message):
        key_name = input(""Enter the key name: "")
        while True:
            try:
                cipher_text, key = self.key_manager.encrypt(message)
                print(f""Encrypted message: {cipher_text}"")
                break
            except ValueError as e:
                print(f""Error: {e}"")

    def verify(self):
        signature = input(""Enter the signature: "")
        if len(signature) == 0:
            return None

        key_name = input(""Enter the key name: "")
        while True:
            try:
                public_key = self.key_manager.keys[key_name]
                verifier = pkcs1_15.new(public_key)
                data = message.encode()
                try:
                    verifier.verify(data, signature.encode())
                    print(f""Signature is valid for {key_name}"")
                    return
                except ValueError as e:
                    print(f""Error: {e}"")
            except KeyError:
                print(""Invalid key name"")
        return None


def main():
    processor = RSAProcessor()
    while True:
        choice = input(""1. Encrypt\n2. Decrypt\n3. Generate Key\n4. Verify Signature\n5. Quit\nChoose an option: "")
        if choice == ""1"":
            message = input(""Enter the message to encrypt: "")
            processor.process(message)
        elif choice == ""2"":
            cipher_text = input(""Enter the cipher text: "")
            print(processor.decrypt(cipher_text))
        elif choice == ""3"":
            key_name = input(""Enter the key name: "")
            public_exponent = int(input(""Enter the public exponent (default is 65537): "") or 65537)
            processor.key_manager.generate_key(key_name, public_exponent)
        elif choice == ""4"":
            message = input(""Enter the message to verify: "")
            processor.verify()
        elif choice == ""5"":
            break
        else:
            print(""Invalid option. Please choose a valid option."")


if __name__ == ""__main__"":
    main()

