def compute_optimized_value(expression):
    def dynamic_programming(expression):
        dp = [[0] * (len(expression) + 1) for _ in range(len(expression) + 1)]
        operators = {'+', '-', '*', '/'}

        for length in range(2, len(expression) + 1):
            for start in range(len(expression) - length + 1):
                end = start + length
                max_val = float('-inf')
                for split_point in range(start + 1, end):
                    left, right = expression[start:split_point], expression[splitpoint:end]
                    if all(op not in left and op not in right for op in operators):
                        if '(' not in left and '(' not in right:
                            left_val, right_val = int(left), int(right)
                            val = max(left_val + dp[splitpoint][end],
                                      right_val + dp[start][splitpoint],
                                      eval(left + expression[splitpoint] + right))
                        else:
                            val = max(eval(f'({left}){expression[splitpoint]}({right})') +
                                      dp[start][splitpoint] +
                                      dp[splitpoint][end],
                                      eval(left.replace('(', '').replace(')', '')) +
                                      eval(right.replace('(', '').replace(')', '')) +
                                      dp[start][end])
                        dp[start][end] = val

        return dp[0][-1]

    def parse_expression(expression):
        stack, temp_stack, num_str, sign_strs = [], [], '', []
        i = 0

        while i < len(expression):
            char = expression[i]

            if char.isdigit() or (char == '-' and i == 0): num_str += char
            elif char == '(':
                stack.append(temp_stack)
                temp_stack.clear()
                sign_strs.append(sign_str)
                num_str, sign_str = '', ''
            elif char == ')':
                prev_signs_strs, prev_temp_stack = sign_strs.pop(), stack.pop()
                prev_temp_stack.append(num_str)
                prev_temp_stack.extend(prev_signs_strs[::-1])
                temp_stack.clear()
                sign_strs.clear()
            else:
                sign_str += char

            i += 1

        return [temp_stack[::-1], ''.join(sign_str)]

    def resolve_dns(ip_address):
        dns_resolution_dict = defaultdict(str)
        for ip in ip_address.split(','):
            if '-' in ip or '.' in ip:
                domain_name = f""www.{ip}""
                if not dns_resolution_dict[domain_name]:
                    result, _ = dynamic_programming(domain_name.replace('(', '-').replace(')', '-'))
                    dns_resolution_dict[domain_name] = str(result)
            else:
                return None
        return dns_resolution_dict

    expression_value = compute_optimized_value(expression)
    parsed_expression = parse_expression(expression)
    return resolve_dns(parsed_expression[1])
