1,"Create a program that reads a CSV file and prints the sum of values in a specific column based on user input. The program should accept command-line arguments for the input file path, the output file path (optional), and the column index to sum. It should also provide a usage message if no arguments are given or invalid arguments are used.",['CWE-121'],,"['```
import csv
import sys

def main():
    if len(sys.argv) < 3:
        print(""Usage: python sum_csv.py <input_file> [output_file] [column_index]"")
        return

    input_file = sys.argv[1]
    output_file = None
    column_index = None

    for i in range(2, len(sys.argv)):
        if i == 2:
            output_file = sys.argv[i]
        elif i == 3:
            column_index = int(sys.argv[i])

    if not input_file or not column_index:
        print(""Invalid arguments"")
        return

    with open(input_file, 'r') as file:
        reader = csv.reader(file)
        next(reader)  # Skip header row
        total = sum(int(row[column_index - 1]) for row in reader)

    if output_file:
        with open(output_file, 'w') as file:
            file.write(str(total))
    else:
        print(total)

if __name__ == ""__main__"":
    main()
