import threading
import random
import requests
import json

class StockPrice:
    def __init__(self, symbol, timestamp, price):
        self.symbol = symbol
        self.timestamp = timestamp
        self.price = price

def fetch_stock_data(symbol):
    try:
        api_url = f""https://www.alphavantage.co/query?function=REALTIME_INTRADAY&symbol={symbol}&interval=1min&apikey=YOUR_API_KEY""
        response = requests.get(api_url)
        data = json.loads(response.text)
        return data[""Realtime Time Series (1min)""][list(data[""Realtime Time Series (1min)"".keys()])[0]]
    except Exception as e:
        print(f""Error fetching stock data for {symbol}: {str(e)}"")
        return None

def get_random_price(symbol, timestamp):
    low_price = 10
    high_price = 100
    price = round(random.uniform(low_price, high_price), 2)
    return StockPrice(symbol, timestamp, price)

class FetchStockTask(threading.Thread):
    def __init__(self, symbol):
        threading.Thread.__init__(self)
        self.symbol = symbol

    def run(self):
        data = fetch_stock_data(self.symbol)
        if data:
            stock_price = get_random_price(self.symbol, data[""1. open""])
            print(f""Stock Price for {self.symbol}: Symbol - {stock.price}, Timestamp - {stock.timestamp}, Price - {stock.price}"")

def main():
    symbols = [""AAPL"", ""MSFT"", ""GOOGL"", ""AMZN""]
    tasks = [FetchStockTask(symbol) for symbol in symbols]

    for task in tasks:
        task.start()
    for task in tasks:
        task.join()

if __name__ == ""__main__"":
    main()
