def optimize_expression(expression, cache):
    if expression in cache:
        return cache[expression]
    else:
        min_operations = float('inf')
        optimal_parentheses = """"

        for i in range(len(expression)):
            for j in range(i + 1, len(expression) + 1):
                subexpr = expression[i:j]
                operations = calculate_subexpression_operations(subexpr)

                if operations < min_operations:
                    min_operations = operations
                    optimal_parentheses = f""({subexpr})""

        cache[expression] = (min_operations, optimal_parentheses)

        return min_operations, optimal_parentheses

def calculate_subexpression_operations(expression):
    operations = 0

    for i in range(len(expression)):
        if expression[i] == '(' or expression[i] == ')':
            operations += 1

    return operations

