import os
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from base64 import b64decode
import random
import networkx as nx

def load_base64_data(file_path):
    with open(file_path, 'rb') as f:
        data = f.read()
    return b64decode(data).decode('utf-8')

def generate_graph(num_vertices=10):
    graph = nx.Graph()
    for i in range(num_vertices):
        graph.add_node(f'node{i}')
    for _ in range(100):  # create edges
        node1 = random.choice(list(graph.nodes))
        node2 = random.choice(list(graph.nodes))
        if node1 != node2:
            graph.add_edge(node1, node2)
    return graph

def generate_triple_des_keys(key_length=8):
    keys = []
    for i in range(3):
        key = os.urandom(key_length)
        keys.append(key)
    return keys

def encrypt_data(data, keys):
    cipher = Cipher(algorithms.TripleDES(), modes.ECB())
    encryptor = cipher.encryptor()
    encrypted_data = b''
    for byte in data.encode('utf-8'):
        if byte > 127:
            raise ValueError(""Invalid character"")
        for key in keys:
            byte ^= ord(key[i % len(key)].encode('utf-8')[0])
        encrypted_data += str(byte).encode('utf-8')
    return encryptor.update(encrypted_data)

def decrypt_data(data, keys):
    cipher = Cipher(algorithms.TripleDES(), modes.ECB())
    decryptor = cipher.decryptor()
    decrypted_data = b''
    for byte in data.encode('utf-8'):
        if byte > 127:
            raise ValueError(""Invalid character"")
        for key in reversed(keys):
            byte ^= ord(key[i % len(key)].encode('utf-8')[0])
        decrypted_data += str(byte).encode('utf-8')
    return decryptor.update(decrypted_data)

def main():
    file_path = 'input.txt'
    num_vertices = 10
    encrypt = False

    if len(sys.argv) > 1:
        file_path = sys.argv[1]
    if len(sys.argv) > 2:
        encrypt = (sys.argv[2].lower() == 'encrypt')

    data = load_base64_data(file_path)

    if not encrypt and sys.stdin.isatty():
        print(data)
        return

    graph = generate_graph(num_vertices)

    keys = generate_triple_des_keys()

    if encrypt:
        encrypted_data = encrypt_data(data, keys)
    else:
        decrypted_data = decrypt_data(data, keys)

    print(encrypted_data.decode('utf-8') if encrypt else decrypted_data.decode('utf-8'))

if __name__ == ""__main__"":
    main()
