import random
from typing import List

def generateRandomSequence(sequence: List[int], length: int) -> None:
    if length >= 100:
        sequence[:] = [random.randint(0, 99) for _ in range(length)]
    else:
        all_numbers = list(range(100))
        random.shuffle(all_numbers)
        sequence[:] = all_numbers[:length]

def verifySequence(sequence: List[int], length: int) -> bool:
    if len(set(sequence)) != length or len(sequence) != length:
        return False
    for i in range(100):
        if i not in set(sequence):
            return False
    return True
