import subprocess
import requests
import os

def modify_kickstart(config_file, params):
    modified_file = config_file + '_modified'
    placeholders = list(params.keys())
    with open(config_file, 'r') as file:
        content = file.read()
        for placeholder in placeholders:
            actual_value = params[placeholder]
            try:
                subprocess.run(['sed', '-i', f's/{placeholder}/{actual_value}/g', config_file], check=True)
            except subprocess.CalledProcessError as e:
                print(f""Error replacing {placeholder} with {actual_value}: {e}"")
                raise

    return modified_file

def get_pokemon_weakness(pokemon_name):
    base_url = ""https://pokeapi.co/api/v2/pokemon/""
    response = requests.get(base_url + pokemon_name.lower())

    if response.status_code == 200:
        data = response.json()
        pokemon_type_1 = data['types'][0]['type']['name']
        pokemon_type_2 = None
        if len(data['types']) > 1:
            pokemon_type_2 = data['types'][1]['type']['name']

        type_weaknesses_api_url = f""https://pokeapi.co/api/v2/type/{pokemon_type_1.lower()}/weaknesses""

        type_weaknesses_response = requests.get(type_weaknesses_api_url)

        if type_weaknesses_response.status_code == 200:
            type_weaknesses_data = type_weaknesses_response.json()

            weaknesses_str_list = []

            for weakness in type_weaknesses_data['results']:
                weaknesses_str_list.append(weakness['name'])

            return ', '.join(weaknesses_str_list)

        else:
            return ""Failed to retrieve weaknesses""

    else:
        return ""Pokemon not found""

def main():
    config_path_example = ""/path/to/config/file.cfg""

    # Example of a dictionary containing placeholder values and actual replacements
    example_params_dict_example = {""variable1"": ""value1"", ""variable2"": ""value2""}

    modified_config_file = modify_kickstart(config_path_example, example_params_dict_example)

    print(modified_config_file)

    pokemon_name_example = ""charizard""
    weaknesses_example = get_pokemon_weakness(pokemon_name_example)

    if weaknesses_example != ""Pokemon not found"":
        print(f""The {pokemon_name_example} is weak against: {weaknesses_example}"")
    else:
        print(f""Failed to retrieve weaknesses for {pokemon_name_example}"")

if __name__ == ""__main__"":
    main()
