import xml.etree.ElementTree as ET
from xml.dom import minidom

def parse_xml_config(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()

    database_details = {}
    for child in root:
        if child.tag == 'database':
            for grandchild in child:
                if grandchild.tag == 'host':
                    database_details['host'] = grandchild.text
                elif grandchild.tag == 'port':
                    database_details['port'] = int(grandchild.text)
                elif grandchild.tag == 'username':
                    database_details['username'] = grandchild.text
                elif grandchild.tag == 'password':
                    database_details['password'] = grandchild.text
                elif grandchild.tag == 'database_name':
                    database_details['database_name'] = grandchild.text

    logging_settings = {}
    for child in root:
        if child.tag == 'logging':
            for grandchild in child:
                if grandchild.tag == 'level':
                    logging_settings['level'] = grandchild.text
                elif grandchild.tag == 'format':
                    logging_settings['format'] = grandchild.text

    return database_details, logging_settings

