import os
from PIL import Image

class ImageViewer:
    def __init__(self):
        self.image_cache = None

    def create_image_cache(self):
        if not os.path.exists('image_cache'):
            os.makedirs('image_cache')
        self.image_cache = 'image_cache'

    def load_image(self, image_path):
        if not self.image_cache:
            self.create_image_cache()
        if not os.path.exists(os.path.join(self.image_cache, os.path.basename(image_path))):
            Image.open(image_path).save(os.path.join(self.image_cache, os.path.basename(image_path)))
        return os.path.join(self.image_cache, os.path.basename(image_path))

    def get_image_metadata(self, image_path):
        try:
            img = Image.open(image_path)
            metadata = {
                'width': img.size[0],
                'height': img.size[1],
                'format': img.format,
                'mode': img.mode
            }
            return metadata
        except Exception as e:
            print(f""Error: {e}"")
            return None

    def load_and_extract_metadata(self, image_path):
        loaded_image = self.load_image(image_path)
        if not loaded_image:
            loaded_image = os.path.join(self.image_cache, 'default_image.jpg')
        metadata = self.get_image_metadata(loaded_image)
        print(metadata)

