import pandas as pd
import matplotlib.pyplot as plt

def load_customer_data():
    customer_data = pd.read_csv('customer_data.csv')
    return customer_data

def filter_customer_data(customer_data, min_age, max_age):
    filtered_data = customer_data[(customer_data['age'] >= min_age) & (customer_data['age'] <= max_age)]
    return filtered_data

def calculate_average_spending(filtered_data):
    average_spending = filtered_data['spending'].mean()
    return average_spending

def generate_bar_chart(customer_data, filtered_data):
    ages = customer_data['age'].unique()
    counts = [len(customer_data[customer_data['age'] == age]) for age in ages]
    plt.bar(ages, counts)
    plt.xlabel('Age')
    plt.ylabel('Count')
    plt.title('Customer Counts by Age Bracket')
    plt.show()

def main():
    customer_data = load_customer_data()
    min_age = int(input(""Enter the minimum age: ""))
    max_age = int(input(""Enter the maximum age: ""))

    filtered_data = filter_customer_data(customer_data, min_age, max_age)

    average_spending = calculate_average_spending(filtered_data)
    print(f""Average spending for customers in the {min_age} to {max_age} age range is ${average_spending:.2f}"")

    generate_bar_chart(customer_data, filtered_data)

if __name__ == ""__main__"":
