import os
import subprocess

def compress_directory(directory_path, output_archive_name):
    try:
        archive_command = f""7z a {output_archive_name}.7z @({directory_path}/*.*)""
        process = subprocess.run(archive_command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
