def determine_valid_state_transitions(nfa_pi_list):
    valid_states = []
    for pdu in nfa_pi_list:
        if pdu.state == 'START':
            valid_states.append(pdu)
        elif pdu.state == 'END':
            continue
        else:
            previous_state = None
            for transition in pdu.transitions:
                if transition.target_state not in valid_states and transition.target_state != previous_state:
                    valid_states.append(transition.target_state)
                    previous_state = transition.target_state
    return [state.transition_pdu for state in valid_states]
