5. **Performance Optimization**: Utilized `raise_for_status()` method to handle HTTP errors more efficiently rather than manually checking status codes using `response.status_code`.",['CWE-590'],,"['```
import requests
from bs4 import BeautifulSoup
import re

def fetch_public_webpage(url, allowed_domains):
    if not url.startswith('http'):
        raise ValueError(""Invalid URL format"")

    if not any(url.endswith(f"".{domain}"") for domain in allowed_domains):
        raise ValueError(""Access restricted to public, non-sensitive websites only"")

    try:
        response = requests.get(url)
        response.raise_for_status()

        soup = BeautifulSoup(response.text, 'html.parser')

        for script in soup(['script', 'style']):
            script.extract()

        extracted_text = "" "".join([p.get_text() for p in soup.find_all('p')])

        return extracted_text

    except requests.RequestException as e:
        raise requests.RequestException(f""Network error fetching {url}: {e}"")
