def calculate_md5_hash(file_path: str) -> str:
    md5 = hashlib.md5()
    with open(file_path, 'rb') as file:
        chunk = file.read(1024)
        while chunk:
            md5.update(chunk)
            chunk = file.read(1024)
    return md5.hexdigest()

def update_fsa_states(state_array: POINTER(c_void_p), num_states: int, fsa_ptr: c_void_p, last_state_idx: int) -> POINTER(StateNode):
