    if not iv and (mode in ['CBC', 'CTR']):
        raise InvalidKey('Initialization vector required for CBC/CTR modes')

    algorithm = algorithms.AES(key)
    if mode == 'ECB':
        return Cipher(algorithm, modes.ECB(), backend=default_backend())
    elif mode == 'CBC':
        return Cipher(algorithm, modes.CBC(iv), backend=default_backend())
    elif mode == 'CTR':
        return Cipher(algorithm, modes.CTR(iv), backend=default_backend())
    elif mode == 'GCM':
        return Cipher(algorithm, modes.GCM(iv), backend=default_backend())

def derive_key(password: bytes, salt: bytes) -> bytes:
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000
    )
    return kdf.derive(password)

def generate_iv(mode: str):
    if mode in ['CBC', 'CTR']:
        return os.urandom(16)
    else:
        return None

def encrypt_decrypt(data: bytes, key: bytes, iv: bytes=None, mode: str='ECB') -> AESMode:
    cipher = aes_cipher(key, iv)
    encrypted_data = cipher.encryptor().update(data)

    if mode == 'GCM':
        associated_data = b'hello world'
        tag = cipher.encryptor().authenticate(associated_data)
        return AESMode(mode, key, iv, tag=tag)
    else:
        return AESMode(mode, key, iv)

def main():
    password = b'password123'
    salt = os.urandom(16)
    derived_key = derive_key(password, salt)

    data = b'message to encrypt'

    mode = 'GCM'
    aes_mode = encrypt_decrypt(data, derived_key, generate_iv(mode))

    print(aes_mode.mode)
    print(aes_mode.key)
    print(aes_mode.iv)
    if mode == 'GCM':
        print(aes_mode.tag)

if __name__ == ""__main__"":
    main()
