from Crypto.Protocol.KDF import scrypt
import os
import base64

class AESEncryption:
    def __init__(self,
                 mode: str,
                 key: bytes,
                 iv: bytes = None,
                 padding: str = ""pkcs7"",
                 block_size: int = 16,
                 salt: bytes = b"""",
                 parallel_processing: bool = False):
        if mode not in ['ecb', 'cbc', 'ctr', 'gcm']:
            raise ValueError('Invalid mode. Choose from ecb, cbc, ctr, gcm.')
        self.mode = mode
        self.key = key
        self.iv = iv if iv else get_random_bytes(block_size)
        self.padding = padding
        self.block_size = block_size
        self.salt = salt if salt else os.urandom(32)
        self.parallel_processing = parallel_processing

    def encrypt(self, plaintext):
        if self.mode == 'ecb':
            cipher = AES.new(self.key, AES.MODE_ECB)
        elif self.mode == 'cbc':
            cipher = AES.new(self.key, AES.MODE_CBC, iv=self.iv)
        elif self.mode == 'ctr':
            cipher = AES.new(self.key, AES.MODE_CTR, nonce=self.iv)
        else:
            cipher = AES.new(self.key, AES.MODE_GCM, iv=self.iv)

        if self.padding == ""pkcs7"":
            from Crypto.Util.Padding import pad
            padded_plaintext = pad(plaintext.encode(), self.block_size)
        else:
            padded_plaintext = plaintext + b'\0' * (self.block_size - len(plaintext) % self.block_size)

        ciphertext = cipher.encrypt(padded_plaintext)

        if self.mode == 'gcm':
            from Crypto.Util.Padding import unpad
            auth_tag = cipher.auth_tag()
            return {'ciphertext': base64.b64encode(ciphertext).decode(), 
                    'auth_tag': base64.b64encode(auth_tag).decode()}
        else:
            return base64.b64encode(ciphertext).decode()

    def decrypt(self, ciphertext):
        if self.mode == 'ecb':
            cipher = AES.new(self.key, AES.MODE_ECB)
        elif self.mode == 'cbc':
            cipher = AES.new(self.key, AES.MODE_CBC, iv=self.iv)
        elif self.mode == 'ctr':
            cipher = AES.new(self.key, AES.MODE_CTR, nonce=self.iv)
        else:
            cipher = AES.new(self.key, AES.MODE_GCM, iv=self.iv)

        if self.mode == 'gcm':
            from Crypto.Util.Padding import unpad
            auth_tag = base64.b64decode(self.ciphertext.split('|')[1])
            ciphertext = base64.b64decode(self.ciphertext.split('|')[0])

            try:
                cipher.update(ciphertext)
            except ValueError:
                return None

        if self.padding == ""pkcs7"":
            from Crypto.Util.Padding import unpad
            plaintext = unpad(cipher.decrypt(base64.b64decode(ciphertext)), self.block_size)
        else:
            plaintext = base64.b64decode(ciphertext).decode()[:-self.block_size]

        return plaintext
