import json
from products import Product

def load_products_from_json(file_name):
    try:
        with open(file_name, 'r') as f:
            products = [Product.from_dict(json.loads(line)) for line in f.readlines()]
    except FileNotFoundError:
        return []

    return products

def main():
    # Load existing products from file
    products = load_products_from_json('products.json')

    # Add new products if needed
    product1 = Product('Product A', 10.99, 100)
    product2 = Product('Product B', 5.99, 50)
    product3 = Product('Product C', 7.99, 75)

    products.extend([product1, product2, product3])

    # Write updated list of products to a new JSON file
    with open('updated_products.json', 'w') as f:
        json.dump([p.to_dict() for p in products], f)

class Product:
    def __init__(self, name, price, stock):
        self.name = name
        self.price = price
        self.stock = stock

    @classmethod
    def from_dict(cls, dictionary):
        return cls(dictionary['name'], dictionary['price'], dictionary['stock'])

    def to_dict(self):
        return {'name': self.name, 'price': self.price, 'stock': self.stock}

if __name__ == ""__main__"":
    main()
