import threading
from contextlib import contextmanager

class DatabaseConnectionManager:
    _instance = None

    def __init__(self):
        self.pool = []
        self.lock = threading.Lock()

    @staticmethod
    def get_instance():
        if not DatabaseConnectionManager._instance:
            DatabaseConnectionManager._instance = DatabaseConnectionManager()
        return DatabaseConnectionManager._instance

    @contextmanager
    def connect(self):
        self.lock.acquire()
        if self.pool:
            conn = self.pool.pop(0)
            try:
                yield conn
            finally:
                self.pool.append(conn)
                self.lock.release()
        else:
            raise ConnectionError(""No available connections in the pool."")

