import threading
import time

class TrafficLight:
    def __init__(self, name):
        self.name = name
        self.color = 'red'
        self.time_left = 0
        self.lock = threading.Lock()

    def set_color(self, color, time):
        with self.lock:
            self.color = color
            self.time_left = time

    def get_state(self):
        with self.lock:
            return f'{self.name} is {self.color}'


class Intersection:
    def __init__(self):
        self.lights = {
            'NS': TrafficLight('North-South'),
            'EW': TrafficLight('East-West'),
            'D': TrafficLight('Diagonal')
        }
        self.clock = time.time()

    def update(self):
        current_time = time.time()
        if current_time - self.clock >= 30:
            self.lights['NS'].set_color('green', 30)
            self.lights['EW'].set_color('red', 60)
            self.lights['D'].set_color('red', 90)
            self.clock = current_time
        elif current_time - self.clock >= 45 and self.lights['NS'].color == 'green':
            for light in self.lights.values():
                light.set_color('yellow', 5)
            time.sleep(5)
            for light in self.lights.values():
                light.set_color('red', 0)
        elif current_time - self.clock >= 75 and self.lights['EW'].color == 'green':
            for light, light_obj in self.lights.items():
                if light != 'NS' and light != 'D':
                    light_obj.set_color('yellow', 5)
            time.sleep(5)
            for key, value in self.lights.items():
                if key != 'NS' and key != 'D':
                    value.set_color('red', 0)

    def get_status(self):
        status = ''
        for name, light in self.lights.items():
            status += f'{light.get_state()}\n'
        return status


if __name__ == ""__main__"":
    intersection = Intersection()
    while True:
        intersection.update()
        print(intersection.get_status())
        time.sleep(0.1)
